import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const AcademySquadPreview = () => {
    const navigate = useNavigate();
    const [missions, setMissions] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchMissions = async () => {
            try {
                const data = await supabaseService.getOpenMissions();
                setMissions(data || []);
            } catch (err) {
                console.error("Failed to fetch open missions:", err);
                // Fallback demo data
                setMissions([
                    { id: 1, name: 'AI Scholarship Automator', mission: 'Tech Development', members_count: 3, description: 'Building a tool to match students to 1000+ global funds automatically.' },
                    { id: 2, name: 'Eco-Impact Venture', mission: 'Social Impact', members_count: 5, description: 'Developing a sustainable community model for West African scholars.' },
                    { id: 3, name: 'LUC Design System V2', mission: 'Design Mastery', members_count: 2, description: 'Crafting the next generation of visual language for the LUC platform.' }
                ]);
            } finally {
                setIsLoading(false);
            }
        };

        fetchMissions();
    }, []);

    return (
        <section className="py-24 bg-slate-950 relative overflow-hidden">
            {/* High-Tech Background Visuals */}
            <div className="absolute inset-0 z-0">
                <div className="absolute top-0 left-1/4 w-px h-full bg-gradient-to-b from-transparent via-emerald-500/20 to-transparent" />
                <div className="absolute top-0 right-1/4 w-px h-full bg-gradient-to-b from-transparent via-primary/20 to-transparent" />
                <div className="absolute top-1/2 left-0 w-full h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.05)_0%,transparent_70%)]" />
            </div>

            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
                <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8 mb-16">
                    <div className="max-w-2xl">
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-emerald-500/10 border border-emerald-500/20 rounded-full mb-6">
                            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping" />
                            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400">Live Mission Board</span>
                        </div>
                        <h2 className="text-4xl md:text-6xl font-black text-white mb-6 italic tracking-tighter leading-[0.9]">
                            Don't Just Learn. <br />
                            <span className="text-emerald-400">Build the Future.</span>
                        </h2>
                        <p className="text-xl text-slate-400 font-medium leading-relaxed">
                            Join elite Project Squads and collaborate with global scholars on real-world ventures. This is where learning becomes impact.
                        </p>
                    </div>
                    <Button
                        size="xl"
                        variant="outline"
                        className="border-white/10 text-white hover:bg-white/5 font-black italic px-10 shadow-2xl"
                        onClick={() => navigate('/academy/project-squads')}
                        iconName="Rocket"
                    >
                        LAUNCH YOUR SQUAD
                    </Button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {isLoading ? (
                        [1, 2, 3].map(i => (
                            <div key={i} className="h-64 bg-white/5 rounded-[2.5rem] animate-pulse" />
                        ))
                    ) : (
                        missions.slice(0, 3).map(mission => (
                            <div key={mission.id} className="group relative bg-white/[0.03] hover:bg-white/[0.07] border border-white/10 rounded-[2.5rem] p-8 transition-all duration-700 hover:-translate-y-2">
                                <div className="absolute -inset-2 bg-emerald-500/10 rounded-[3rem] blur-xl opacity-0 group-hover:opacity-100 transition-opacity duration-700" />

                                <div className="relative z-10">
                                    <div className="flex items-center justify-between mb-6">
                                        <div className="px-3 py-1 bg-emerald-500/10 rounded-lg text-[9px] font-black uppercase tracking-widest text-emerald-400 border border-emerald-500/20">
                                            {mission.mission}
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <div className="flex -space-x-2">
                                                {[1, 2].map(i => (
                                                    <img key={i} src={`https://i.pravatar.cc/100?u=${mission.id + i}`} className="w-6 h-6 rounded-full border-2 border-slate-900" alt="Member" />
                                                ))}
                                            </div>
                                            <span className="text-[10px] font-black text-slate-500">+{mission.members_count || 1} Building</span>
                                        </div>
                                    </div>

                                    <h4 className="text-2xl font-black text-white italic mb-4 tracking-tighter group-hover:text-emerald-400 transition-colors">
                                        {mission.name}
                                    </h4>

                                    <p className="text-slate-400 text-sm font-medium mb-8 line-clamp-2 leading-relaxed">
                                        {mission.description}
                                    </p>

                                    <div className="flex items-center justify-between pt-6 border-t border-white/5">
                                        <button
                                            onClick={() => navigate('/academy/project-squads')}
                                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 group-hover:text-white transition-colors flex items-center gap-2"
                                        >
                                            <Icon name="Users" size={14} />
                                            View Mission
                                        </button>
                                        <Button
                                            size="sm"
                                            variant="secondary"
                                            className="rounded-xl font-black italic scale-90 group-hover:scale-100 transition-transform"
                                            onClick={() => navigate('/academy/project-squads')}
                                        >
                                            JOIN SQUAD
                                        </Button>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Real-time Ticker */}
                <div className="mt-20 py-6 border-y border-white/5 flex items-center gap-12 overflow-hidden whitespace-nowrap opacity-50">
                    <div className="flex items-center gap-12 animate-marquee">
                        {[1, 2, 3, 4, 5].map(i => (
                            <div key={i} className="flex items-center gap-3">
                                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white">
                                    {i === 1 ? "New Squad Formed: Tech Ventures" : i === 2 ? "Scholar Inducted: Global Impact Mission" : "LUC Reward Issued: +100 Credits"}
                                </span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <style dangerouslySetInnerHTML={{
                __html: `
                @keyframes marquee {
                    0% { transform: translateX(0); }
                    100% { transform: translateX(-50%); }
                }
                .animate-marquee {
                    display: flex;
                    animation: marquee 30s linear infinite;
                }
            `}} />
        </section>
    );
};

export default AcademySquadPreview;
